import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = list(reader)
    if not records:
        return {"columns": ["", "", "", ""], "rows": []}

    # The first record is the single header row.
    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")
    width = 4

    if len(columns) < width:
        columns.extend([""] * (width - len(columns)))
    elif len(columns) > width:
        columns = columns[:width - 1] + [";".join(columns[width - 1:])]

    rows = []
    for record in records[1:]:
        if len(record) < width:
            record.extend([""] * (width - len(record)))
        elif len(record) > width:
            record = record[:width - 1] + [";".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
